// Part: roofs and chimneys. The main hip, the dormers and trusses come from roof.json (runParts lays it after the shell);
// this part adds the four brick stacks with their room hearths, and the hand-built shed roof over the rear porch.
import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { chimneyStack, CHIMNEYS } from "../vocab.mjs";

const OPPOSITE = { north: "south", south: "north", east: "west", west: "east" };
const STEP = { north: [0, -1], south: [0, 1], east: [1, 0], west: [-1, 0] };

// One firebox in a stack face: the stack cell on the room side is carved to air, a lit campfire stands in its floor
// row (y), air above it to y+1, and a brick stair lintel (upside-down, into the stack) closes it at y+2.
function firebox(g, x, y, z, face) {
  g.set(x, y, z, "air");
  g.set(x, y + 1, z, "air");
  g.set(x, y, z, "campfire", { facing: face, lit: "true" });
  g.set(x, y + 2, z, ...B.stairs("brick", OPPOSITE[face], "top"));
}

// Hearths on every stack face that opens onto a room (air at the room cell on both floors): y4..5 ground, y11..12 upper.
function hearths(g, sx, sz) {
  // the firebox cell on each face: the stack cell nearest that face
  const cells = { east: [sx + 1, sz], west: [sx, sz], north: [sx, sz], south: [sx + 1, sz + 1] };
  for (const face of ["east", "west", "north", "south"]) {
    const [fx, fz] = cells[face];
    const [dx, dz] = STEP[face];
    for (const floor of [3, 10]) {
      const room = g.blockAt(fx + dx, floor + 1, fz + dz);
      if (room && room !== "air") continue;
      firebox(g, fx, floor + 1, fz, face);
    }
  }
}

// Shed roof over the rear porch (plan ROOFS, R-rearporch): high against the wing wall z75 at y10 (z76..78), low at the
// eave y9 (z79..80), stairs facing north so the slope falls to the south. Solid slate under the high rows, which sit
// on air above the porch beam (y8).
function rearPorchRoof(g) {
  const [x0, x1] = [37, 58];
  for (let x = x0; x <= x1; x++) {
    for (let z = 76; z <= 78; z++) {
      g.set(x, 9, z, "deepslate_tiles");
      g.set(x, 10, z, ...B.stairs("deepslate_tile", "north", "bottom"));
    }
    for (let z = 79; z <= 80; z++) g.set(x, 9, z, ...B.stairs("deepslate_tile", "north", "bottom"));
  }
}

export function build(g) {
  // ---- chimney stacks: the footing from y0, through both floors and the roof, capped with a signal fire
  for (const [x, z] of CHIMNEYS) {
    chimneyStack(g, x, z, { y: 0 });
    g.set(x, 27, z, "campfire", { facing: "north", lit: "true", signal_fire: "true" });
  }
  // ---- hearths in the rooms (after the stacks, so their fireboxes carve the stack cells)
  for (const [x, z] of CHIMNEYS) hearths(g, x, z);

  // ---- rear porch shed roof (the porch itself and its beam are the colonnade part's)
  rearPorchRoof(g);
}

